INSERT INTO "yards" (id, source, "yardNumber", name, slug, address, city, state, zip, country, latitude, longitude, phone, email, "contactName", hours, notes, "physicalInspectionAvailable", "isActive", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'IAAI', v."yardNumber", v.name,
       CASE WHEN EXISTS (SELECT 1 FROM "yards" y WHERE y.slug = v.slug AND NOT (y.source = 'IAAI' AND y."yardNumber" = v."yardNumber")) THEN NULL ELSE v.slug END,
       v.address, v.city, v.state, v.zip, 'US', v.latitude, v.longitude, v.phone, v.email, v."contactName", v.hours, v.notes,
       false, true, NOW(), NOW()
FROM v
ON CONFLICT (source, "yardNumber") DO UPDATE SET
  name          = COALESCE(NULLIF("yards".name, ''), EXCLUDED.name),
  slug          = COALESCE("yards".slug, EXCLUDED.slug),
  address       = COALESCE(NULLIF("yards".address, ''), EXCLUDED.address),
  city          = COALESCE(NULLIF("yards".city, ''), EXCLUDED.city),
  state         = COALESCE(NULLIF("yards".state, ''), EXCLUDED.state),
  zip           = COALESCE(NULLIF("yards".zip, ''), EXCLUDED.zip),
  country       = COALESCE(NULLIF("yards".country, ''), EXCLUDED.country),
  latitude      = COALESCE("yards".latitude, EXCLUDED.latitude),
  longitude     = COALESCE("yards".longitude, EXCLUDED.longitude),
  phone         = COALESCE(NULLIF("yards".phone, ''), EXCLUDED.phone),
  email         = COALESCE(NULLIF("yards".email, ''), EXCLUDED.email),
  "contactName" = COALESCE(NULLIF("yards"."contactName", ''), EXCLUDED."contactName"),
  hours         = COALESCE("yards".hours, EXCLUDED.hours),
  notes         = COALESCE(NULLIF("yards".notes, ''), EXCLUDED.notes),
  "updatedAt"   = NOW();
